22: function simulateTargetET(spec) {
23:   const sim = new DragSim(spec);
24:   for (let i = 0; i < 240; i++) {
25:     const thr = sim.engineRpm < spec.launchRpm ? 1 : 0.15;
26:     sim.step(dt, { throttle: thr, clutch: true }, true);
27:     if (sim.engineRpm >= spec.launchRpm) break;
28:   }
29:   let t = 0;
30:   let guard = 0;
31:   while (sim.distance < FINISH && guard++ < 120 * 22) {
32:     const thr = sim.wheelspin > 0.6 ? 0.65 : 1;
33:     sim.step(dt, { throttle: thr, clutch: false }, false);
34:     sim.autoShift();
35:     t += dt;
36:   }
37:   return t;
38: }
