```js
export function gaugeTexture(kind) {
  const tach = kind === "tach";
  return canvasTex(`gauge:${kind}`, 256, 256, (ctx, w, h) => {
    const cx = w / 2, cy = h / 2, R = w / 2 - 4;
    ctx.clearRect(0,0,w,h);
    // face
    const face = ctx.createRadialGradient(cx, cy - 20, 10, cx, cy, R);
    face.addColorStop(0, "#101218");
    face.addColorStop(1, "#05060a");
    ctx.fillStyle = face;
    ctx.beginPath(); ctx.arc(cx, cy, R - 2, 0, Math.PI * 2); ctx.fill();
    // redline arc
    const a0 = 2.25, a1 = -2.25;
    if (tach) {
      ctx.strokeStyle = "#ff2a1a";
      ctx.lineWidth = 10;
      const start = a0 - 4.5 * 0.72;
      ctx.beginPath();
      ctx.arc(cx, cy, R - 12, -start, -a1); // canvas angles: y down, so negate
      ctx.stroke();
    }
    ...
  });
}
