/**
 * Captura de janela/aba/tela ao vivo — o equivalente no navegador ao que o
 * PrismTextureStreamer faz no ETS2 com o hook de DirectX: pega uma fonte
 * externa e usa como textura das telas da cabine.
 *
 * Usa getDisplayMedia (escolha da janela pelo próprio navegador) e VideoTexture
 * do Three.js. Uma mesma fonte alimenta as duas telas, cada uma com seu
 * enquadramento (a tela central é larga, o retrovisor é bem panorâmico).
 */
export class WindowFeed {
  constructor() {
    this.stream = null;
    this.active = false;
    this.fps = 15;
    this.onchange = null;
    this.onmeta = null;
    this._ended = this._ended.bind(this);

    this.video = document.createElement("video");
    this.video.muted = true;
    this.video.playsInline = true;
    this.video.autoplay = true;
    this.video.setAttribute("playsinline", "");
    this.video.addEventListener("loadedmetadata", () => this._onMeta());
    this.video.addEventListener("resize", () => this._onMeta());

    this.dashTexture = this._videoTexture(false);
    this.mirrorTexture = this._videoTexture(true);
    this.dashMaterial = new THREE.MeshBasicMaterial({ map: this.dashTexture, toneMapped: false });
    this.mirrorMaterial = new THREE.MeshBasicMaterial({ map: this.mirrorTexture, toneMapped: false });
    // visível mesmo com a cabine escura
    this.dashMaterial.color.setScalar(1.08);
    this.mirrorMaterial.color.setScalar(1.08);

    this.dashAspect = 0.31 / 0.113;
    this.mirrorAspect = 0.17 / 0.038;
  }

  _videoTexture(flip) {
    const tex = new THREE.VideoTexture(this.video);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    tex.generateMipmaps = false;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.userData.flip = flip;
    return tex;
  }

  get videoSize() {
    return { width: this.video.videoWidth || 0, height: this.video.videoHeight || 0 };
  }

  /** Encaixa o vídeo na proporção da tela sem esticar (letterbox/crop). */
  _fit(texture, planeAspect) {
    const { width: vw, height: vh } = this.videoSize;
    let rx = 1;
    let ry = 1;
    if (vw && vh) {
      const videoAspect = vw / vh;
      if (videoAspect > planeAspect) rx = planeAspect / videoAspect;
      else ry = videoAspect / planeAspect;
    }
    const ox = (1 - rx) / 2;
    const oy = (1 - ry) / 2;
    const flip = !!texture.userData.flip;
    texture.repeat.set(flip ? -rx : rx, ry);
    texture.offset.set(flip ? ox + rx : ox, oy);
  }

  _onMeta() {
    this._fit(this.dashTexture, this.dashAspect);
    this._fit(this.mirrorTexture, this.mirrorAspect);
    this.onmeta?.(this.videoSize);
  }

  /** Abre o seletor de janela do navegador. */
  async start({ fps = 15 } = {}) {
    if (!navigator.mediaDevices?.getDisplayMedia) {
      const err = new Error("captura de tela não suportada neste navegador");
      err.code = "unsupported";
      throw err;
    }
    const stream = await navigator.mediaDevices.getDisplayMedia({
      video: {
        frameRate: { ideal: fps, max: fps },
        width: { ideal: 1920 },
        height: { ideal: 1080 },
      },
      audio: false,
    });
    this.attach(stream);
    this.setFps(fps);
    return stream;
  }

  /** Liga uma fonte já existente (stream do getDisplayMedia, canvas.captureStream...). */
  attach(stream) {
    this.detach();
    if (!stream) return;
    this.stream = stream;
    this.video.srcObject = stream;
    this.video.play().catch(() => { /* autoplay bloqueado: o frame fica no último quadro */ });
    this.active = true;
    for (const track of stream.getVideoTracks()) {
      track.addEventListener("ended", this._ended);
    }
    this._fit(this.dashTexture, this.dashAspect);
    this._fit(this.mirrorTexture, this.mirrorAspect);
    this.onchange?.("start");
  }

  _ended() {
    if (!this.active) return;
    this.stop("ended");
  }

  setFps(fps) {
    this.fps = fps;
    for (const track of this.stream?.getVideoTracks() || []) {
      track.applyConstraints({ frameRate: { ideal: fps, max: fps } }).catch(() => { /* fonte fixa */ });
    }
  }

  stop(reason = "stop") {
    if (this.stream) {
      for (const track of this.stream.getTracks()) {
        track.removeEventListener("ended", this._ended);
        track.stop();
      }
    }
    this.stream = null;
    this.video.srcObject = null;
    this.active = false;
    this.onchange?.(reason);
  }

  detach() {
    if (this.stream) {
      for (const track of this.stream.getTracks()) {
        track.removeEventListener("ended", this._ended);
        track.stop();
      }
    }
    this.stream = null;
    this.video.srcObject = null;
    this.active = false;
  }
}
