    const idx = Math.max(0, Math.min(N, Math.round(sWorld / ds)));
    return lineState[idx];
  }
  function nextCorner(sWorld) {
    let out = null;
    for (const c of corners) {
      if (c.exit > sWorld + 4) {
        if (!out || c.entry < out.entry) out = c;
