import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')

const width = 1280
const height = 720
const out = process.env.OUT || '/tmp/opencode/shots'
const fs = await import('node:fs')
fs.mkdirSync(out, { recursive: true })

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 })
const errors = []
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()) })
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message))

await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' })
await page.waitForTimeout(700)
await page.screenshot({ path: join(out, '01-boot.jpg'), type: 'jpeg', quality: 72 })

const boot = page.locator('#btn-boot')
if (await boot.isVisible()) await boot.click()
await page.waitForTimeout(1400)
await page.screenshot({ path: join(out, '02-menu.jpg'), type: 'jpeg', quality: 72 })

await page.click('#btn-race')
await page.waitForTimeout(1800)
await page.screenshot({ path: join(out, '03-start.jpg'), type: 'jpeg', quality: 72 })

// segura embreagem + gás e solta no verde
await page.keyboard.down('Space')
await page.keyboard.down('KeyW')
await page.waitForTimeout(900)
await page.keyboard.up('Space')
await page.waitForTimeout(2600)
await page.screenshot({ path: join(out, '04-race.jpg'), type: 'jpeg', quality: 72 })

const state1 = await page.evaluate(() => {
  const g = window.__dragBrasil
  return {
    mode: g.mode, phase: g.phase, gear: g.playerSim.gear, speed: g.playerSim.speedKmh,
    dist: g.playerSim.distance, finish: g.finishDistance, lateral: g.playerSim.lateral,
    corners: g.track.corners.length, startS: g.startS, finishS: g.track.FINISH_S,
    crashed: g.playerSim.crashes,
  }
})

// segue reto por mais tempo para pegar uma troca de marcha e curva
await page.waitForTimeout(6000)
await page.screenshot({ path: join(out, '05-shift.jpg'), type: 'jpeg', quality: 72 })
const state2 = await page.evaluate(() => {
  const g = window.__dragBrasil
  return {
    mode: g.mode, phase: g.phase, gear: g.playerSim.gear, rpm: Math.round(g.playerSim.rpmNorm * 100) / 100,
    speed: Math.round(g.playerSim.speedKmh), dist: Math.round(g.playerSim.distance),
    lateral: Math.round(g.playerSim.lateral * 100) / 100, crashes: g.playerSim.crashes,
    steer: Math.round(g.steer * 100) / 100,
    advice: document.getElementById('rl-advice')?.textContent,
    corner: document.getElementById('rl-corner')?.textContent,
    hudGear: document.getElementById('hud-gear')?.textContent,
  }
})

// câmera externa para conferir piloto e carro
await page.keyboard.press('KeyC')
await page.waitForTimeout(900)
await page.screenshot({ path: join(out, '06-chase.jpg'), type: 'jpeg', quality: 72 })

await page.keyboard.up('KeyW')
console.log(JSON.stringify({ state1, state2, errors }, null, 2))
await browser.close()

