import * as THREE from "three";

const CONTROL = [
  [0, -80], [0, -20], [0, 40], [0, 120], [0, 200], [0, 270],
  [10, 320], [38, 352], [78, 362],
  [118, 360], [152, 352],
  [178, 334], [186, 306], [200, 282], [226, 274],
  [262, 280], [298, 296],
  [322, 320], [350, 334], [382, 330],
  [410, 322], [438, 300], [450, 270], [446, 238], [424, 216], [394, 212],
  [358, 210], [318, 212], [282, 218],
  [252, 228], [228, 240],
  [204, 238], [184, 232], [168, 220], [158, 202], [154, 180],
  [152, 150], [150, 120], [148, 90], [148, 60],
  [156, 40], [176, 28], [200, 26],
  [240, 26], [280, 32],
  [312, 48], [344, 54], [378, 48], [400, 30], [430, 22], [470, 20], [510, 26],
  [540, 36], [560, 50], [572, 74], [576, 102],
  [578, 140], [580, 180],
  [592, 212], [614, 232], [642, 238],
  [690, 240], [740, 236],
  [800, 228], [860, 214], [920, 206], [980, 208],
];

const curve = new THREE.CatmullRomCurve3(CONTROL.map(([x, z]) => new THREE.Vector3(x, 0, z)), false, "centripetal", 0.5);
const total = curve.getLength();
const N = Math.round(total / 2);
const pts = curve.getSpacedPoints(N);
console.log("total", total.toFixed(1), "N", N);

// self proximity
let worst = { d: Infinity, i: 0, j: 0 };
for (let i = 0; i <= N; i += 2) {
  for (let j = i + 40; j <= N; j += 2) {
    const d = pts[i].distanceTo(pts[j]);
    if (d < worst.d) worst = { d, i, j };
  }
}
console.log("min non-neighbour distance", worst.d.toFixed(2), "at", worst.i, worst.j, pts[worst.i], pts[worst.j]);

const heading = [];
for (let i = 0; i <= N; i++) {
  const a = pts[Math.max(0, i - 1)], b = pts[Math.min(N, i + 1)];
  heading.push(Math.atan2(b.x - a.x, b.z - a.z));
}
const ds = total / N;
const kappa = [];
for (let i = 0; i <= N; i++) {
  let d = heading[Math.min(N, i + 1)] - heading[Math.max(0, i - 1)];
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  kappa.push(d / (2 * ds));
}
const sm = kappa.map((_, i) => {
  let sum = 0, w = 0;
  for (let j = -4; j <= 4; j++) {
    const idx = Math.max(0, Math.min(N, i + j));
    sum += kappa[idx] * (5 - Math.abs(j));
    w += 5 - Math.abs(j);
  }
  return sum / w;
});
for (const th of [0.008, 0.01, 0.0105, 0.014, 0.02]) {
  let n = 0, inside = false;
  const arr = [];
  for (let i = 0; i <= N; i++) {
    if (Math.abs(sm[i]) > th) {
      if (!inside) { inside = true; n++; arr.push({ at: (i * ds).toFixed(0), r: Math.round(1 / Math.abs(sm[i])) }); }
    } else inside = false;
  }
  console.log("th", th, "corners", n, JSON.stringify(arr));
}
// start point
let si = 0, bd = Infinity;
for (let i = 0; i <= N; i++) { const d = pts[i].x ** 2 + pts[i].z ** 2; if (d < bd) { bd = d; si = i; } }
console.log("start", (si * ds).toFixed(1), "finish", (total - 150).toFixed(1), "race", (total - 150 - si * ds).toFixed(1));

