import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch(cfg.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' })
await page.bringToFront()
await page.waitForTimeout(600)
await page.click('#btn-boot')
await page.waitForTimeout(800)
await page.click('#btn-race')
await page.waitForTimeout(1500)
const out = await page.evaluate(() => {
  const g = window.__dragBrasil
  g.greenReached = true; g.phase = 'racing'; g.cameraMode = 'cockpit'; g.playerRunStart = 0
  g.playerSim.distance = 240; g.playerSim.speed = 78; g.playerSim.gear = 4
  g.updateCarVisuals(0.016)
  g.updateCamera(0.6); g.updateCamera(0.6)
  g.renderer.render(g.scene, g.camera)
  const p = g.playerModel
  const wp = new (g.scene.position.constructor)()
  p.steeringWheel.getWorldPosition(wp)
  const cam = g.camera
  const proj = (v) => {
    const q = v.clone().project(cam)
    return { x: Math.round((q.x * 0.5 + 0.5) * 1280), y: Math.round((-q.y * 0.5 + 0.5) * 720), z: +q.z.toFixed(3) }
  }
  const wheelCenterLocal = new (g.scene.position.constructor)(-0.37, 0.842, 0.315)
  const wheelWorld = g.playerGroup.localToWorld(wheelCenterLocal.clone())
  const arm = p.driver ? null : null
  const hand = new (g.scene.position.constructor)()
