import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync, mkdirSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const out = '/tmp/opencode/shots3'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch(cfg.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
const errors = []
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message))
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' })
await page.waitForTimeout(500)
await page.click('#btn-boot')
await page.waitForTimeout(600)
await page.click('#btn-race')
await page.waitForTimeout(1100)

await page.evaluate(() => {
  const g = window.__dragBrasil
  g.update = function () {}
  g.playerSim.distance = 240
  g.playerSim.speed = 78
  g.playerSim.gear = 4
  g.playerSim.engineRpm = g.playerSpec.redline * 0.82
  g.greenReached = true
  g.phase = 'racing'
  g.playerRunStart = 0
  g.cameraMode = 'cockpit'
  g.playerGroup.localToWorld(new g.playerGroup.position.constructor())
  g.updateCarVisuals(0.016)
  // câmera original (antes das minhas mudanças)
  g.playerGroup.updateMatrixWorld(true)
  const cam = g.camera
  const V = g.playerGroup.position.constructor
  cam.position.copy(g.playerGroup.localToWorld(new V(-0.37, 1.215, -0.31)))
  cam.rotation.set(-0.075, g.playerGroup.rotation.y + Math.PI, 0, 'YXZ')
  cam.fov = 66
  cam.updateProjectionMatrix()
  g.ui.toast('')
  g.renderer.render(g.scene, g.camera)
})

const hits = await page.evaluate(async () => {
  const g = window.__dragBrasil
  const THREE = await import('/node_modules/three/build/three.module.js')
  const rc = new THREE.Raycaster()
  const pts = [
    [0, -0.05], [0, -0.3], [0, -0.6], [0, -0.85],
    [-0.25, -0.1], [0.25, -0.1], [-0.45, 0.05], [0.45, 0.05],
    [-0.2, 0.0], [0.2, 0.0], [-0.6, -0.2], [0.6, -0.2], [-0.1, 0.25], [0.1, 0.25],
  ]
  return pts.map(([x, y]) => {
    rc.setFromCamera(new THREE.Vector2(x, y), g.camera)
    const hit = rc.intersectObject(g.playerGroup, true).find((h) => h.object.visible)
    const ph = rc.intersectObjects(g.scene.children, true).filter((h) => h.object.visible)[0]
    const d = (h) => d0(h)
    function d0(h) {
      if (!h) return null
      const m = h.object.material
      return {
        geo: h.object.geometry?.type,
        color: m?.color ? '#' + m.color.getHexString() : null,
        map: !!m?.map,
        y: +h.point.y.toFixed(2),
        z: +h.point.z.toFixed(2),
        dist: +h.distance.toFixed(2),
        name: h.object.name || h.object.parent?.name || '',
      }
    }
    return { ndc: [x, y], car: d(hit), any: d(ph) }
  })
})
console.log(JSON.stringify({ hits, errors }, null, 2))
await page.screenshot({ path: join(out, 'original-cam.png') })
await browser.close()

