await page.click('#btn-boot')
await page.waitForTimeout(600)
await page.click('#btn-race')
await page.waitForTimeout(1100)

const data = await page.evaluate(() => {
  const g = window.__dragBrasil
  g.update = function () {}
  g.playerSim.distance = 240
  g.playerSim.speed = 78
  g.playerSim.gear = 4
  g.playerSim.engineRpm = g.playerSpec.redline * 0.82
  g.greenReached = true
  g.phase = 'racing'
  g.playerRunStart = 0
  g.cameraMode = 'cockpit'
  g.updateCarVisuals(0.016)
  g.updateCamera(0.6)
  g.updateCamera(0.6)
  g.renderer.render(g.scene, g.camera)

  const V = g.playerGroup.position.constructor
  const p = g.playerModel
  const cam = g.camera
  const project = (v) => {
    const q = v.clone().project(cam)
    return { x: (q.x * 0.5 + 0.5) * 1280, y: (-q.y * 0.5 + 0.5) * 720 }
  }
  const pts = {
    wheelCenter: project(g.playerGroup.localToWorld(new V(-0.37, 0.842, 0.315))),
    rimTop: project(g.playerGroup.localToWorld(new V(-0.37, 0.997, 0.315))),
    rimBottom: project(g.playerGroup.localToWorld(new V(-0.37, 0.687, 0.315))),
    dashBadge: project(g.playerGroup.localToWorld(new V(0.4, 0.995, 0.346))),
    cluster: project(g.playerGroup.localToWorld(new V(-0.355, 1.016, 0.355))),
    gearBox: project(g.playerGroup.localToWorld(new V(-0.37, 1.072, 0.292))),
    shifter: project(g.playerGroup.localToWorld(new V(0.06, 1.085, 0.13))),
    extinguisher: project(g.playerGroup.localToWorld(new V(0.45, 1.1, -0.3))),
    dashNear: project(g.playerGroup.localToWorld(new V(-0.37, 1.045, 0.46))),
    dashFar: project(g.playerGroup.localToWorld(new V(-0.37, 1.045, 0.8))),
    hoodNear: project(g.playerGroup.localToWorld(new V(0, 1.07, 1.0))),
    hoodFar: project(g.playerGroup.localToWorld(new V(0, 1.07, 2.2))),
    horizon: project(g.playerGroup.localToWorld(new V(0, 1.225, 20))),
  }
  // left hand / right hand world positions
  const hands = []
  if (p.driver?.arms) {
    for (const a of p.driver.arms) {
      const v = new V()
      a.hand.getWorldPosition(v)
      hands.push(project(v))
    }
  }
  return { pts, hands, eye: cam.position.toArray(), rot: [cam.rotation.x, cam.rotation.y, cam.rotation.z], groupRot: g.playerGroup.rotation.y }
})
