import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))

const browser = await chromium.launch(cfg.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' })
await page.waitForTimeout(500)
await page.click('#btn-boot')
await page.waitForTimeout(600)
await page.click('#btn-race')
await page.waitForTimeout(1100)

const data = await page.evaluate(() => {
  const g = window.__dragBrasil
  const THREE = window.__THREE
  g.update = function () {}
  g.playerSim.distance = 240
  g.playerSim.speed = 78
  g.playerSim.gear = 4
  g.playerSim.engineRpm = g.playerSpec.redline * 0.82
  g.greenReached = true
  g.phase = 'racing'
  g.playerRunStart = 0
  g.cameraMode = 'cockpit'
  g.updateCarVisuals(0.016)
  g.updateCamera(0.6)
  g.updateCamera(0.6)
  g.renderer.render(g.scene, g.camera)

  const vis = (o) => { let a = o; while (a) { if (!a.visible) return false; a = a.parent } return true }
  const info = (o) => ({
    color: o.material?.color ? '#' + o.material.color.getHexString() : null,
    map: !!o.material?.map,
    pos: o.position.toArray().map((v) => +v.toFixed(2)),
    geo: o.geometry?.type,
  })
  const rc = new THREE.Raycaster()
  const samples = [[0, -0.2], [0, -0.35], [0, -0.55], [0, -0.75], [0.1, -0.65], [-0.1, -0.6], [0.2, 0.0], [-0.2, 0.0]]
  const out = samples.map(([x, y]) => {
    rc.setFromCamera(new THREE.Vector2(x, y), g.camera)
    const hits = rc.intersectObject(g.playerGroup, true).filter((h) => vis(h.object))
    const h = hits[0]
    return { ndc: [x, y], hit: h ? { ...info(h.object), dist: +h.distance.toFixed(2), point: h.point.toArray().map((v) => +v.toFixed(2)), chains: (() => { const names = []; let a = h.object.parent; while (a) { names.push(a.type + (a.visible ? '' : '(hidden)')); a = a.parent } return names.slice(0, 4) })() } : null }
  })
  return {
    torsoVisible: g.playerModel.driver.torso.visible,
    headVisible: g.playerModel.driver.head.visible,
    armsVisible: g.playerModel.driver.arms.map((a) => ({ upper: a.upper.visible, fore: a.fore?.visible, hand: a.hand.visible })),
    shadowVisible: g.playerModel.root.children[0].visible,
    out,
  }
})
