86: function wheel(x, z, side, front) {
87:   const g = new THREE.Group();
88:   g.position.set(x, 0.345, z);
89:   const steerGroup = new THREE.Group();
90:   const spin = new THREE.Group();
91:   g.add(steerGroup);
92:   steerGroup.add(spin);
93: 
94:   const r = 0.345;
95:   const width = 0.29;
96:   const tireGeo = new THREE.CylinderGeometry(r, r, width, 28, 1);
97:   tireGeo.rotateZ(Math.PI / 2);
98:   mesh(tireGeo, mats.tire, spin);
99: 
100:   // sulcos
101:   const groove = new THREE.MeshStandardMaterial({ color: 0x1d1d22, roughness: 0.9 });
102:   for (let i = -2; i <= 2; i++) {
103:     const ring = new THREE.Mesh(new THREE.TorusGeometry(r * 0.9, 0.012, 6, 36), groove);
104:     ring.rotation.y = Math.PI / 2;
105:     ring.position.x = i * 0.055;
106:     spin.add(ring);
107:   }
108: 
109:   const rimGeo = new THREE.CylinderGeometry(r * 0.63, r * 0.63, width + 0.02, 24);
110:   rimGeo.rotateZ(Math.PI / 2);
111:   mesh(rimGeo, mats.rimDark, spin, false);
112:   const face = new THREE.CylinderGeometry(r * 0.64, r * 0.64, 0.03, 24);
113:   face.rotateZ(Math.PI / 2);
114:   const faceMesh = mesh(face, mats.rim, spin, false);
115:   faceMesh.position.x = side * (width / 2 + 0.005);
116: 
117:   // raios
118:   const spokeMat = mats.rim;
119:   for (let i = 0; i < 5; i++) {
120:     const a = (i / 5) * Math.PI * 2;
121:     const sp = new THREE.Mesh(new THREE.BoxGeometry(0.035, r * 1.1, 0.075), spokeMat);
122:     sp.position.set(side * (width / 2 + 0.03), Math.sin(a) * 0.02, 0);
123:     sp.rotation.x = a;
124:     spin.add(sp);
125:   }
126:   const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.04, 16), mats.chrome);
127:   cap.rotation.z = Math.PI / 2;
128:   cap.position.x = side * (width / 2 + 0.02);
129:   spin.add(cap);
130: 
131:   // pinça de freio
132:   const caliper = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.16, 0.1), new THREE.MeshStandardMaterial({ color: 0xff4a12, roughness: 0.4, metalness: 0.4 }));
133:   caliper.position.set(side * 0.02, 0.16, 0.08);
134:   steerGroup.add(caliper);
135: 
136:   return { group: g, steerGroup, spin, side, front };
137: }
