117:   for (let i = startIdx + 1; i <= finishIdx; i++) {
118:     profile[i] = Math.min(profile[i], Math.sqrt(profile[i - 1] * profile[i - 1] + 2 * ACCEL_ACC * ds));
119:   }
120:   for (let i = 0; i <= N; i++) {
121:     const next = profile[Math.min(N, i + 1)];
122:     const dv = next - profile[i];
123:     lineState[i] = dv < -0.045 ? 1 : dv > 0.045 ? 2 : 0;
