126:   // deslocamento da linha ideal: por dentro da curva
127:   const lineOff = new Float32Array(N + 1);
128:   for (let i = 0; i <= N; i++) {
129:     let sum = 0;
130:     for (let j = -5; j <= 5; j++) sum += kappa[Math.max(0, Math.min(N, i + j))];
131:     lineOff[i] = Math.max(-2.4, Math.min(2.4, (sum / 11) * 120));
