137:   let corner = null;
138:   for (let i = startIdx; i <= N; i++) {
139:     const k = Math.abs(kappa[i]);
140:     if (k > 0.0105) {
141:       if (!inCorner) {
142:         inCorner = true;
143:         corner = { entry: i * ds, apex: i * ds, exit: i * ds, radius: 1 / k, dir: Math.sign(kappa[i]), speed: profile[i] };
144:       }
145:       if (k > 1 / corner.radius) {
146:         corner.radius = 1 / k;
147:         corner.apex = i * ds;
148:         corner.speed = profile[i];
149:       }
150:       corner.exit = i * ds;
151:     } else if (inCorner) {
152:       inCorner = false;
153:       if (corner.exit - corner.entry > 14) corners.push(corner);
154:     }
155:   }
