161:   function frameAt(sWorld, out = {}) {
162:     const u = Math.max(0, Math.min(N - 0.0001, sWorld / ds));
163:     const i = Math.floor(u);
164:     const f = u - i;
165:     const tx = lerp(tanX[i], tanX[i + 1], f);
166:     const tz = lerp(tanZ[i], tanZ[i + 1], f);
167:     const inv = 1 / (Math.hypot(tx, tz) || 1);
168:     out.x = lerp(pts[i].x, pts[i + 1].x, f);
169:     out.z = lerp(pts[i].z, pts[i + 1].z, f);
170:     out.tx = tx * inv;
171:     out.tz = tz * inv;
172:     out.nx = out.tz; // normal à direita
173:     out.nz = -out.tx;
174:     out.heading = Math.atan2(out.tx, out.tz);
175:     out.kappa = lerp(kappa[i], kappa[i + 1], f);
176:     out.s = sWorld;
177:     return out;
178:   }
