180:   function strip(offset, width, y, uvScale = 0) {
181:     const positions = [];
182:     const uvs = [];
183:     const indices = [];
184:     for (let i = 0; i <= N; i++) {
185:       const nx = tanZ[i];
186:       const nz = -tanX[i];
187:       const cx = pts[i].x + nx * offset;
188:       const cz = pts[i].z + nz * offset;
189:       positions.push(cx + nx * (-width / 2), y, cz + nz * (-width / 2));
190:       positions.push(cx + nx * (width / 2), y, cz + nz * (width / 2));
191:       uvs.push(0, i * ds * (uvScale || 1 / 9), 1, i * ds * (uvScale || 1 / 9));
192:       if (i < N) {
193:         const a = i * 2;
194:         indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
195:       }
196:     }
197:     const geo = new THREE.BufferGeometry();
198:     geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
199:     geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
200:     geo.setIndex(indices);
201:     geo.computeVertexNormals();
202:     return geo;
203:   }
