193:   nextRival() {
194:     const idx = clamp(this.save.careerWins, 0, RIVALS.length - 1);
195:     const base = RIVALS[idx];
196:     const extraCycles = Math.max(0, this.save.careerWins - (RIVALS.length - 1));
197:     const power = RIVAL_POWER[idx] + extraCycles * 0.035;
198:     const info = { ...base, power, idx };
199:     info.target = this.rivalTarget(info);
200:     return info;
201:   }
202: 
203:   rivalTarget(info) {
204:     const key = `${info.car}:${JSON.stringify(info.upgrades)}:${info.power.toFixed(3)}`;
205:     if (this.rivalTargetCache.has(key)) return this.rivalTargetCache.get(key);
206:     const spec = buildSpec(carById(info.car), info.upgrades);
207:     spec.torque *= info.power;
208:     const t = simulateTargetET(spec, this.track);
209:     this.rivalTargetCache.set(key, t);
210:     return t;
211:   }
