213:   // ---------- input ----------
214:   initInput() {
215:     const bindHold = (el, down, up) => {
216:       if (!el) return;
217:       const d = (e) => {
218:         e.preventDefault();
219:         try { el.setPointerCapture(e.pointerId); } catch { /* ignore */ }
220:         down();
221:       };
222:       const u = () => up();
223:       el.addEventListener("pointerdown", d);
224:       el.addEventListener("pointerup", u);
225:       el.addEventListener("pointercancel", u);
226:       el.addEventListener("lostpointercapture", u);
227:     };
228: 
229:     bindHold(document.getElementById("btn-gas"), () => {
230:       this.touchGas = true;
231:     }, () => {
232:       this.touchGas = false;
233:     });
234:     bindHold(document.getElementById("btn-brake"), () => {
235:       this.touchClutch = true;
236:     }, () => {
237:       this.touchClutch = false;
238:     });
239: 
240:     const shiftUp = document.getElementById("btn-shift-up");
241:     const shiftDown = document.getElementById("btn-shift-down");
242:     const pressShift = (dir) => (e) => {
243:       e.preventDefault();
244:       this.tryShift(dir);
245:     };
246:     shiftUp.addEventListener("pointerdown", pressShift(1));
247:     shiftDown.addEventListener("pointerdown", pressShift(-1));
248:     const autoBtn = document.getElementById("btn-auto");
249:     autoBtn.classList.toggle("on", this.autoShift);
250:     autoBtn.addEventListener("pointerdown", (e) => {
251:       e.preventDefault();
252:       this.autoShift = !this.autoShift;
253:       autoBtn.classList.toggle("on", this.autoShift);
254:       this.audio.ui();
255:     });
256: 
257:     const pad = document.getElementById("wheel-pad");
258:     const updateWheel = (e) => {
259:       const r = pad.getBoundingClientRect();
260:       const dx = (e.clientX - (r.left + r.width / 2)) / (r.width * 0.5);
261:       this.steerTarget = clamp(dx * 1.15, -1, 1);
262:     };
263:     pad.addEventListener("pointerdown", (e) => {
264:       e.preventDefault();
265:       this.wheelPointer = e.pointerId;
266:       try { pad.setPointerCapture(e.pointerId); } catch { /* ignore */ }
267:       updateWheel(e);
268:     });
269:     pad.addEventListener("pointermove", (e) => {
270:       if (this.wheelPointer === e.pointerId) updateWheel(e);
271:     });
272:     const releaseWheel = () => {
273:       this.wheelPointer = null;
274:       this.steerTarget = 0;
275:     };
276:     pad.addEventListener("pointerup", releaseWheel);
277:     pad.addEventListener("pointercancel", releaseWheel);
278:     pad.addEventListener("lostpointercapture", releaseWheel);
279: 
280:     window.addEventListener("keydown", (e) => {
281:       if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Space"].includes(e.code)) e.preventDefault();
282:       this.keys[e.code] = true;
283:       if (e.repeat) return;
284:       if (e.code === "KeyC") this.toggleCamera();
285:       if (e.code === "KeyP") this.togglePrism();
286:       if (e.code === "ShiftLeft" || e.code === "ShiftRight" || e.code === "KeyE") this.tryShift(1);
287:       if (e.code === "ControlLeft" || e.code === "ControlRight" || e.code === "KeyQ") this.tryShift(-1);
288:       if (e.code === "Escape") {
289:         if (this.mode === "race") this.openMenu();
290:         else if (this.mode === "garage" || this.mode === "help") this.openMenu();
291:       }
292:     });
293:     window.addEventListener("keyup", (e) => {
294:       this.keys[e.code] = false;
295:     });
296:     window.addEventListener("blur", () => {
297:       this.keys = {};
298:       this.touchGas = false;
299:       this.touchClutch = false;
300:     });
301:     // evita menu de contexto ao segurar os pedais
302:     document.querySelectorAll(".pedal, .shift-btn, .wheel-pad").forEach((el) => {
303:       el.addEventListener("contextmenu", (e) => e.preventDefault());
304:     });
305:   }
306: 
307:   tryShift(dir) {
308:     if (this.mode !== "race" || !this.greenReached || this.playerFinished) return;
309:     const sim = this.playerSim;
310:     const ok = dir > 0 ? sim.shiftUp() : sim.shiftDown();
311:     if (ok) {
312:       this.audio.pop(0.6);
313:       this.audio.whoosh();
314:       this.spawnBackfire();
315:       this.playerModel?.driver?.shift();
316:     }
317:   }
318: 
319:   playerInput() {
320:     const k = this.keys;
321:     const gas = !!(k.KeyW || k.ArrowUp || this.touchGas);
322:     const pedal = !!(k.KeyS || k.ArrowDown || this.touchClutch);
323:     let throttle = gas ? 1 : 0;
324:     let clutch = !!(k.Space) || (pedal && !this.greenReached);
325:     let brake = this.greenReached && pedal ? 1 : 0;
326:     if (this.playerFinished) {
327:       throttle = 0;
328:       clutch = false;
329:       brake = 1;
330:     }
331:     return { throttle, clutch, steer: this.steer, brake };
332:   }
333: 
334:   playerClutchPressed() {
335:     const k = this.keys;
336:     return !!(k.Space || (!this.greenReached && (k.KeyS || k.ArrowDown || this.touchClutch)));
337:   }
