339:   // ---------- camera ----------
340:   toggleCamera() {
341:     if (this.mode !== "race" && this.mode !== "result") return;
342:     this.cameraMode = this.cameraMode === "cockpit" ? "chase" : "cockpit";
343:     this.audio.ui();
344:   }
345: 
346:   updateCamera(rdt) {
347:     const cam = this.camera;
348:     const px = this.playerGroup.position.x;
349:     const pz = this.playerGroup.position.z;
350:     const t = this.time;
351: 
352:     const inside = this.mode === "race" && this.cameraMode === "cockpit";
353:     if (this.playerModel?.windshieldGlass) this.playerModel.windshieldGlass.visible = !inside;
354:     if (this.playerModel?.sideGlassParts) for (const m of this.playerModel.sideGlassParts) m.visible = !inside;
355:     if (this.playerModel?.roofParts) for (const m of this.playerModel.roofParts) m.visible = !inside;
356:     if (this.playerModel?.driver) {
357:       // na câmera interna o capacete/torso ficariam dentro da lente
358:       this.playerModel.driver.head.visible = !inside;
359:       this.playerModel.driver.torso.visible = !inside;
360:     }
361:     if (this.playerModel?.driverSeatParts) {
362:       for (const m of this.playerModel.driverSeatParts) m.visible = !inside;
363:     }
364:     if (this.playerModel?.floorMatParts) {
365:       for (const m of this.playerModel.floorMatParts) m.visible = !inside;
366:     }
367:     if (this.playerModel?.driver?.arms) {
368:       // no cockpit sobram só os antebraços e as mãos, estilo primeira pessoa
369:       for (const a of this.playerModel.driver.arms) {
370:         a.upper.visible = !inside;
371:         a.shoulderJoint.visible = !inside;
372:         a.elbowJoint.visible = !inside;
373:       }
374:     }
375:     if (this.mode === "menu" || this.mode === "boot" || this.mode === "help") {
376:       const a = 0.68 + Math.sin(t * 0.11) * 0.22;
377:       const r = 8.6;
378:       const target = new THREE.Vector3(px + Math.sin(a) * r, 2.85 + Math.sin(t * 0.19) * 0.12, pz + Math.cos(a) * r);
379:       cam.position.lerp(target, 1 - Math.exp(-rdt * 2.2));
380:       cam.lookAt(px, 0.82, pz + 0.15);
381:       cam.fov += (58 - cam.fov) * Math.min(1, rdt * 2);
382:       cam.updateProjectionMatrix();
383:       return;
384:     }
385: 
386:     if (this.mode === "garage") {
387:       const a = 1.02 + Math.sin(t * 0.1) * 0.1;
388:       const r = 7.6;
389:       const target = new THREE.Vector3(px + Math.sin(a) * r, 2.15, pz + Math.cos(a) * r);
390:       cam.position.lerp(target, 1 - Math.exp(-rdt * 2.4));
391:       cam.lookAt(px, 0.78, pz + 0.1);
392:       cam.fov += (52 - cam.fov) * Math.min(1, rdt * 2);
393:       cam.updateProjectionMatrix();
394:       return;
395:     }
396: 
397:     if (this.mode === "result") {
398:       const a = 0.9 + t * 0.12;
399:       const r = 8.6;
400:       cam.position.lerp(new THREE.Vector3(px + Math.sin(a) * r, 2.6, pz + Math.cos(a) * r), 1 - Math.exp(-rdt * 2));
401:       cam.lookAt(px, 0.9, pz + 0.4);
402:       cam.fov += (52 - cam.fov) * Math.min(1, rdt * 2);
403:       cam.updateProjectionMatrix();
404:       return;
405:     }
406: 
407:     // race
408:     const sim = this.playerSim;
409:     this.playerGroup.updateMatrixWorld(true);
410:     const speedN = Math.min(1, sim.speed / 75);
411:     if (this.cameraMode === "chase") {
412:       const back = 7.4 + speedN * 1.8;
413:       const target = this.playerGroup.localToWorld(new THREE.Vector3(0, 2.55 + speedN * 0.2, -back));
414:       cam.position.lerp(target, 1 - Math.exp(-rdt * 5));
415:       const look = this.playerGroup.localToWorld(new THREE.Vector3(0, 1.0, 1.6));
416:       cam.lookAt(look);
417:       cam.fov += (60 + speedN * 16 - cam.fov) * Math.min(1, rdt * 4);
418:       cam.updateProjectionMatrix();
419:       return;
420:     }
421: 
422:     // cockpit
423:     const accel = sim.accel;
424:     const crash = this.crashShake || 0;
425:     const shake = Math.min(0.035, sim.speed * 0.00007 + sim.wheelspin * 0.01 + crash * 0.03);
426:     const base = this.playerGroup.localToWorld(new THREE.Vector3(-0.37, 1.235, -0.30));
427:     base.x += Math.sin(t * 53) * shake;
428:     base.y += Math.sin(t * 61 + 1.3) * shake * 0.7;
429:     base.z += Math.cos(t * 47) * shake * 0.5;
430:     cam.position.copy(base);
431:     const pitch = -0.07 - accel * 0.0035 + Math.sin(t * 44) * shake * 0.35;
432:     const roll = -this.steer * 0.03 * speedN + Math.sin(t * 37) * shake * 0.3;
433:     const yaw = this.steer * 0.05 * speedN;
434:     cam.rotation.set(pitch, this.playerGroup.rotation.y + Math.PI + yaw, roll + this.playerGroup.rotation.z * 0.8, "YXZ");
435:     const fov = 64 + speedN * 13 + Math.min(3, sim.wheelspin * 3);
436:     cam.fov += (fov - cam.fov) * Math.min(1, rdt * 4);
437:     cam.updateProjectionMatrix();
438:   }
