507:   selectCar(id) {
508:     const save = this.save;
509:     const car = carById(id);
510:     const owned = save.ownedCars.includes(id);
511:     if (!owned) {
512:       if (save.money < car.price) {
513:         this.uiToast(`Faltam ${money(car.price - save.money)} pra levar o ${car.name}.`);
514:         return;
515:       }
516:       save.money -= car.price;
517:       save.ownedCars.push(id);
518:       save.paints[id] = PAINTS[CARS.indexOf(car) % PAINTS.length].id;
519:       if (!save.upgrades[id]) save.upgrades[id] = { engine: 0, tires: 0, weight: 0, gearbox: 0 };
520:       save.selected = id;
521:       persist(save);
522:       this.rebuildPlayerCar();
523:       this.ui.renderGarage(save);
524:       this.uiToast(`${car.name} comprado!`);
525:       this.audio.ui();
526:       return;
527:     }
528:     if (save.selected === id) return;
529:     save.selected = id;
530:     persist(save);
531:     this.rebuildPlayerCar();
532:     this.ui.renderGarage(save);
533:     this.ui.updateMenu(save, this.nextRival());
534:     this.audio.ui();
535:   }
