541:       const p = PAINTS.find((x) => x.id === paintId);
542:       if (p) this.playerModel.setPaint(p.hex);
543:     }
544:     this.ui.renderGarage(this.save);
545:     const p = PAINTS.find((x) => x.id === paintId);
