550:   buyUpgrade(id) {
551:     const save = this.save;
552:     const carId = save.selected;
553:     const upg = UPGRADES.find((u) => u.id === id);
554:     if (!upg) return;
555:     const ups = save.upgrades[carId] || (save.upgrades[carId] = { engine: 0, tires: 0, weight: 0, gearbox: 0 });
556:     const lvl = ups[id] | 0;
557:     if (lvl >= upg.max) return;
558:     const cost = upgradeCost(upg, lvl);
559:     if (save.money < cost) {
560:       this.uiToast(`Sem caixa. Faltam ${money(cost - save.money)}.`);
561:       return;
562:     }
563:     save.money -= cost;
564:     ups[id] = lvl + 1;
565:     persist(save);
566:     this.playerSpec = buildSpec(carById(carId), ups);
567:     this.ui.renderGarage(save);
568:     this.ui.updateMenu(save, this.nextRival());
