888:   // ---------- Prism: captura ao vivo nas telas ----------
889:   ensureWindowFeed() {
890:     if (this.windowFeed) return this.windowFeed;
891:     const feed = new WindowFeed();
892:     feed.onchange = (reason) => {
893:       if (reason === "ended") {
894:         // o usuário parou o compartilhamento pelo navegador
895:         this.prism.dash = "telemetry";
896:         this.prism.mirror = "camera";
897:         this.applyCabinScreens();
898:         this.ui?.syncPrism(this.prism);
899:         this.ui?.setPrismActive(false);
900:         this.ui?.setPrismStatus("Compartilhamento encerrado");
901:         this.uiToast("PRISM desconectado");
902:       }
903:     };
904:     feed.onmeta = ({ width, height }) => {
905:       if (feed.active && width && height) this.ui?.setPrismStatus(`${width}×${height} · ao vivo`, true);
906:     };
907:     this.windowFeed = feed;
908:     return feed;
909:   }
910: 
911:   applyCabinScreens() {
912:     const model = this.playerModel;
913:     if (!model) return;
914:     const feed = this.windowFeed;
915:     const live = !!feed?.active;
916:     if (model.dashScreen) {
917:       model.dashScreen.material = live && this.prism.dash === "capture" ? feed.dashMaterial : this.telemetry.material;
918:     }
919:     if (model.mirrorGlass) {
920:       model.mirrorGlass.material = live && this.prism.mirror === "capture" ? feed.mirrorMaterial : this.mirrorFeed.material;
921:     }
922:   }
923: 
924:   setPrismSource(target, source) {
925:     if (target !== "dash" && target !== "mirror") return;
926:     this.prism[target] = source;
927:     if (source === "capture" && !this.windowFeed?.active) {
928:       // ainda não há fonte: abre o seletor e já liga essa tela
929:       this.startPrismCapture();
930:       return;
931:     }
932:     this.applyCabinScreens();
933:     this.ui?.syncPrism(this.prism);
934:   }
935: 
936:   setPrismFps(fps) {
937:     this.prism.fps = fps;
938:     this.windowFeed?.setFps(fps);
939:     this.ui?.syncPrism(this.prism);
940:   }
941: 
942:   setPrismFit(fit) {
943:     this.prism.fit = fit;
944:     this.windowFeed?.setFit(fit);
945:     this.ui?.syncPrism(this.prism);
946:   }
947: 
948:   async startPrismCapture() {
949:     if (this.prismPending) return;
950:     this.prismPending = true;
951:     const request = (this.prismToken = (this.prismToken || 0) + 1);
952:     const feed = this.ensureWindowFeed();
953:     this.ui?.setPrismStatus("Escolha uma janela, aba ou tela…");
954:     try {
955:       await feed.start({ fps: this.prism.fps, fit: this.prism.fit });
956:     } catch (err) {
957:       this.prismPending = false;
958:       const msg = err?.code === "unsupported"
959:         ? "Este navegador não captura janelas"
960:         : err?.name === "NotAllowedError"
961:           ? "Captura cancelada"
962:           : "Falha ao abrir a captura";
963:       if (this.prism.dash === "capture") this.prism.dash = "telemetry";
964:       if (this.prism.mirror === "capture") this.prism.mirror = "camera";
965:       this.applyCabinScreens();
966:       this.ui?.syncPrism(this.prism);
967:       this.ui?.setPrismStatus(msg);
968:       this.ui?.setPrismActive(false);
969:       this.uiToast(msg);
970:       return;
971:     }
972:     this.prismPending = false;
973:     if (request !== this.prismToken) {
974:       // o usuário desistiu enquanto o seletor estava aberto
975:       feed.stop();
976:       return;
977:     }
978:     if (this.prism.dash !== "capture" && this.prism.mirror !== "capture") this.prism.dash = "capture";
979:     this.applyCabinScreens();
980:     this.ui?.syncPrism(this.prism);
981:     this.ui?.setPrismActive(true);
982:     this.ui?.setPrismStatus("Captura ao vivo · tela central", true);
983:     this.uiToast("PRISM CONECTADO");
984:   }
985: 
986:   stopPrismCapture() {
987:     this.prismToken = (this.prismToken || 0) + 1;
988:     this.windowFeed?.stop();
989:     this.prism.dash = "telemetry";
990:     this.prism.mirror = "camera";
991:     this.applyCabinScreens();
992:     this.ui?.syncPrism(this.prism);
993:     this.ui?.setPrismActive(false);
994:     this.ui?.setPrismStatus("Nenhuma captura ativa");
995:   }
