1004:   // ---------- telas vivas (feed de textura) ----------
1005:   updateLiveScreens(rdt) {
1006:     const sim = this.playerSim;
1007:     if (!sim || !this.telemetry) return;
1008: 
1009:     if (this.windowFeed?.active) this.windowFeed.update();
1010: 
1011:     const dashLive = this.prism.dash === "capture" && this.windowFeed?.active;
1012:     const mirrorLive = this.prism.mirror === "capture" && this.windowFeed?.active;
1013: 
1014:     const interval = this.mode === "race" ? 1 / 12 : 1 / 6;
1015:     if (!dashLive && this.time - (this.screenClock || 0) >= interval) {
1016:       this.screenClock = this.time;
1017:       const rsim = this.rivalSim;
1018:       this.telemetry.draw({
1019:         mode: this.mode,
1020:         time: this.time,
1021:         speed: sim.speedKmh,
1022:         rpm: sim.rpmNorm,
1023:         gear: sim.gear,
1024:         distance: sim.distance,
1025:         finish: this.finishDistance,
1026:         gap: rsim ? rsim.distance - sim.distance : null,
1027:         et: (this.mode === "race" || this.mode === "result") && this.playerFinished ? this.playerET : null,
1028:         phase: this.mode === "race" || this.mode === "result"
1029:           ? this.playerFinished ? "FIM" : this.greenReached ? "CORRIDA" : "PREPARE"
1030:           : undefined,
1031:       });
1032:     }
1033: 
1034:     if (this.mirrorFeed && !mirrorLive) {
1035:       const cockpit = this.mode === "race" && this.cameraMode === "cockpit";
1036:       this.mirrorAcc = (this.mirrorAcc || 0) + rdt;
1037:       if (this.mirrorAcc >= (cockpit ? 1 / 15 : 1 / 6)) {
1038:         this.mirrorAcc = 0;
1039:         this.mirrorFeed.update(this.playerGroup);
1040:       }
1041:     }
1042:   }
