1044:   // ---------- loop ----------
1045:   updateCarVisuals(rdt) {
1046:     const p = this.playerModel;
1047:     if (p) {
1048:       const sim = this.playerSim;
1049:       const f = this.track.frameAt(this.startS + sim.distance);
1050:       const bank = clamp(f.kappa * sim.speed * sim.speed * 0.0045, -0.1, 0.1);
1051:       this.track.placeAt(this.playerGroup, this.startS + sim.distance, this.track.LANE + sim.lateral, bank);
1052:       const spin = (sim.speed / this.playerSpec.wheelRadius) * rdt;
1053:       for (const w of p.wheels) {
1054:         w.spin.rotation.x -= spin;
1055:         w.steerGroup.rotation.y = w.front ? this.steer * 0.42 : 0;
1056:       }
1057:       if (p.steeringWheel) p.steeringWheel.rotation.z = this.steer * 1.0;
1058:       if (p.needles.tach) p.needles.tach.rotation.z = 2.25 - sim.rpmNorm * 4.5;
1059:       if (p.needles.speed) p.needles.speed.rotation.z = 2.25 - Math.min(1, sim.speedKmh / 240) * 4.5;
1060:       if (sim.gear !== this._gearShown) {
1061:         this._gearShown = sim.gear;
1062:         p.setGear?.(sim.gear);
