598:     this.greenReached = false;
599:     this.greenClock = null;
600:     this.foul = false;
601:     this.playerRunStart = null;
602:     this.playerReaction = null;
603:     this.playerFinished = false;
604:     this.rivalFinished = false;
605:     this.playerET = null;
606:     this.playerTrap = 0;
607:     this.rivalET = null;
608:     this.rivalTrap = 0;
609:     this.endScheduled = null;
610:     this.launchPromptVisible = false;
611:     this.lastClutch = false;
612:     this.smokeAcc = 0;
613:     this.treeBeeped = [false, false, false];
614:     this.greenBeeped = false;
615:     this.treeStart = 1.25 + Math.random() * 0.65;
616:     this.amberTimes = [this.treeStart, this.treeStart + 0.6, this.treeStart + 1.2];
617:     this.greenAt = this.treeStart + 1.72;
618: 
619:     const info = this.nextRival();
620:     this.rivalInfo = info;
621:     this.rivalReaction = 0.15 + Math.random() * 0.13 + Math.max(0, (1 - info.idx / 8)) * 0.05;
622: 
623:     // specs e sims
624:     this.playerSpec = buildSpec(carById(this.save.selected), this.save.upgrades[this.save.selected] || {});
625:     this.playerSim = new DragSim(this.playerSpec);
626:     const rspec = buildSpec(carById(info.car), info.upgrades);
627:     rspec.torque *= info.power;
628:     this.rivalSpec = rspec;
629:     this.rivalSim = new DragSim(rspec);
630: 
631:     // modelos
632:     this.playerSim.reset();
633:     this.playerSim.clutch = true;
634:     this.playerSim.prevClutch = true;
635:     this.track.placeAt(this.playerGroup, this.startS - 1.4, this.track.LANE);
636:     this.crashShake = 0;
637:     this._gearShown = 0;
638:     this.playerModel.setPaint(PAINTS.find((p) => p.id === (this.save.paints[this.save.selected] || "laranja"))?.hex || "#ff5a12");
639:     const rivalEntry = this.rivalModels[info.car];
640:     for (const key of Object.keys(this.rivalModels)) this.rivalModels[key].group.visible = key === info.car;
641:     rivalEntry.model.setPaint(RIVAL_PAINTS[info.idx % RIVAL_PAINTS.length]);
642:     rivalEntry.group.visible = true;
643:     this.track.placeAt(rivalEntry.group, this.startS - 1.4, -this.track.LANE);
644: 
645:     this.track.setTree({ a: [false, false, false], green: false, red: false });
646:     this.effects.clear();
647:     this.ui.showHUD(info.name);
648:     this.ui.setPhase("PREPARE-SE");
649:     this.ui.setLaunchText("A LUZ VERDE ACENDEU", "ACELERA!");
650:     this.ui.showLaunch(false);
651:     this.ui.showFoul(false);
652:     this.speedlines.style.opacity = "0";
653:     this.steer = 0;
654:     this.steerTarget = 0;
655:   }
