657:   updateTree() {
658:     if (!this.greenReached) {
659:       const t = this.raceClock;
660:       const ambers = this.amberTimes.map((at) => t >= at);
661:       this.track.setTree({ a: ambers, green: false, red: this.foul });
662:       this.ui.setTree(ambers, false, this.foul);
663:       for (let i = 0; i < 3; i++) {
664:         if (!this.treeBeeped[i] && t >= this.amberTimes[i]) {
665:           this.treeBeeped[i] = true;
666:           if (!this.foul) this.audio.beep(620 + i * 45, 0.08, 0.12, "square");
667:         }
668:       }
669:       if (t >= this.treeStart && this.phase === "staging") {
670:         this.phase = "tree";
671:         this.ui.setPhase("LUZES ACESAS");
672:       }
673:       if (t >= this.greenAt) this.onGreen();
674:     } else {
675:       this.track.setTree({ a: [false, false, false], green: !this.foul, red: this.foul });
676:       this.ui.setTree([false, false, false], !this.foul, this.foul);
677:     }
678:   }
