680:   onGreen() {
681:     if (this.greenReached) return;
682:     this.greenReached = true;
683:     this.greenClock = this.raceClock;
684:     this.phase = "racing";
685:     this.ui.setPhase(this.foul ? "QUEIMOU" : "VAI!");
686:     if (!this.foul) {
687:       this.audio.beep(980, 0.25, 0.18, "square");
688:       this.ui.showLaunch(true);
689:       this.ui.setLaunchText("SOLTE A EMBREAGEM E PISA", "VAI!");
690:       this.ui.toast("VERDE! SOLTA A EMBREAGEM", 900);
691:     }
692:   }
