694:   registerFoul() {
695:     this.foul = true;
696:     this.ui.showFoul(true);
697:     this.ui.showLaunch(false);
698:     this.ui.setPhase("QUEIMOU");
699:     this.audio.foul();
700:   }
701: 
702:   stepRace(h) {
703:     if (this.mode !== "race") return;
704:     if (this.phase === "idle") return;
705: 
706:     const pin = !this.greenReached;
707:     const pInput = this.playerInput();
708:     const pFrame = this.track.frameAt(this.startS + this.playerSim.distance);
709:     pInput.curvature = pFrame.kappa;
710:     pInput.lateralLimit = 3.9;
711:     const clutchNow = this.playerClutchPressed();
712: 
713:     if (!this.greenReached && !this.foul && this.lastClutch && !clutchNow && pInput.throttle > 0.15) {
714:       this.registerFoul();
715:     }
716:     this.lastClutch = clutchNow;
717: 
718:     this.playerSim.step(h, pInput, pin);
719:     if (this.playerSim.crashed) {
720:       this.crashShake = 1;
721:       this.audio.beep(90, 0.18, 0.3, "sawtooth");
722:       this.ui.toast("BATEU NO MURO!", 900);
723:     }
724:     if (this.autoShift && this.greenReached && !this.playerFinished) {
725:       const before = this.playerSim.gear;
726:       this.playerSim.autoShift();
727:       if (this.playerSim.gear !== before) {
728:         this.audio.pop(0.6);
729:         this.audio.whoosh();
730:         this.spawnBackfire();
731:         this.playerModel?.driver?.shift();
732:       }
733:     }
734: 
735:     // rival: segue a pista e freia para as curvas
736:     const rSim = this.rivalSim;
737:     const locked = !this.greenReached;
738:     const rThrottle = rSim.engineRpm < this.rivalSpec.launchRpm ? 1 : 0.15;
739:     const rFrame = this.track.frameAt(this.startS + rSim.distance);
740:     const look = Math.min(this.finishDistance, rSim.distance + 16 + rSim.speed * 0.55);
741:     const rTarget = this.track.speedAt(this.startS + look) * 0.93;
742:     let rInput;
743:     if (locked) {
744:       rInput = { throttle: rThrottle, clutch: true, steer: 0, brake: 0, curvature: rFrame.kappa };
745:     } else if (this.raceClock < this.greenClock + this.rivalReaction) {
746:       rInput = { throttle: rThrottle, clutch: true, steer: 0, brake: 0, curvature: rFrame.kappa };
747:     } else if (this.rivalFinished) {
748:       rInput = { throttle: 0, clutch: false, steer: 0, brake: 1, curvature: rFrame.kappa };
749:     } else if (rSim.speed > rTarget + 1.2) {
750:       rInput = { throttle: 0, clutch: false, steer: 0, brake: 0.85, curvature: rFrame.kappa };
751:     } else if (rSim.speed > rTarget - 1.2) {
752:       rInput = { throttle: rSim.wheelspin > 0.6 ? 0.5 : 0.35, clutch: false, steer: 0, brake: 0.15, curvature: rFrame.kappa };
753:     } else {
754:       rInput = { throttle: rSim.wheelspin > 0.6 ? 0.65 : 1, clutch: false, steer: 0, brake: 0, curvature: rFrame.kappa };
755:     }
756:     rSim.step(h, rInput, locked);
757:     if (this.greenReached && !this.rivalFinished && !locked) {
758:       const before = rSim.gear;
759:       rSim.autoShift();
760:       if (rSim.gear !== before) this.spawnBackfire(true);
761:     }
762: 
763:     // chegadas
764:     if (!this.playerFinished && this.playerSim.distance >= this.finishDistance) {
765:       this.playerFinished = true;
766:       this.playerFinishClock = this.raceClock;
767:       this.playerET = this.playerRunStart != null ? this.raceClock - this.playerRunStart : null;
768:       this.playerTrap = this.playerSim.speedKmh;
769:       this.ui.toast(`CHEGOU! ${this.playerET ? this.playerET.toFixed(3) + "s" : ""}`, 1600);
770:       this.audio.pop(1);
771:     }
772:     if (!this.rivalFinished && rSim.distance >= this.finishDistance) {
773:       this.rivalFinished = true;
774:       this.rivalFinishClock = this.raceClock;
775:       this.rivalET = this.raceClock - (this.greenClock + this.rivalReaction);
776:       this.rivalTrap = rSim.speedKmh;
777:     }
778:   }
779: 
780:   spawnBackfire(rival = false) {
781:     const model = rival ? this.rivalModels[this.rivalInfo?.car]?.model : this.playerModel;
782:     if (!model) return;
783:     const pos = new THREE.Vector3();
784:     for (const tip of model.exhaustTips) {
785:       tip.getWorldPosition(pos);
786:       this.effects.emitBackfire(pos, new THREE.Vector3(0, 0.2, -1));
787:     }
788:   }
789: 
790:   updateRace(rdt) {
791:     this.raceClock += rdt;
792:     this.updateTree();
793: 
794:     if (this.greenReached && !this.playerRunStart && this.playerSim.speed > 0.25) {
795:       this.playerRunStart = this.raceClock;
796:       this.playerReaction = this.raceClock - this.greenClock;
797:       this.launchPromptVisible = false;
798:       this.ui.showLaunch(false);
799:       if (!this.foul) {
