19: 
20: function simulateTargetET(spec, course) {
21:   const top = Math.min(
22:     86,
23:     (spec.redline / 60 / (spec.gears[spec.gears.length - 1] * spec.finalDrive)) * 2 * Math.PI * spec.wheelRadius
24:   );
25:   let t = 2.0;
26:   for (let d = 0; d < course.FINISH; d += 5) {
27:     const v = Math.min(top, course.speedAt(course.START_S + d));
28:     t += 5 / Math.max(9, v);
29:   }
30:   return t;
31: }
