780:   spawnBackfire(rival = false) {
781:     const model = rival ? this.rivalModels[this.rivalInfo?.car]?.model : this.playerModel;
782:     if (!model) return;
783:     const pos = new THREE.Vector3();
784:     for (const tip of model.exhaustTips) {
785:       tip.getWorldPosition(pos);
786:       this.effects.emitBackfire(pos, new THREE.Vector3(0, 0.2, -1));
787:     }
788:   }
