790:   updateRace(rdt) {
791:     this.raceClock += rdt;
792:     this.updateTree();
793: 
794:     if (this.greenReached && !this.playerRunStart && this.playerSim.speed > 0.25) {
795:       this.playerRunStart = this.raceClock;
796:       this.playerReaction = this.raceClock - this.greenClock;
797:       this.launchPromptVisible = false;
798:       this.ui.showLaunch(false);
799:       if (!this.foul) {
800:         const rt = this.playerReaction;
801:         const label = rt < 0.16 ? "LARGADA PERFEITA" : rt < 0.34 ? "BOA LARGADA" : "SAIU ATRASADO";
802:         this.ui.toast(`${label} · ${rt.toFixed(3)}s`, 1300);
803:         if (rt < 0.16) this.audio.beep(1200, 0.12, 0.1, "triangle");
804:       }
805:     }
806: 
807:     // fim de corrida
808:     if (this.playerFinished && this.rivalFinished && this.endScheduled == null) {
809:       this.endScheduled = this.raceClock;
810:     }
811:     if (this.playerFinished && !this.rivalFinished && this.raceClock - this.playerFinishClock > 5 && this.endScheduled == null) {
812:       this.endScheduled = this.raceClock;
813:     }
814:     if (!this.playerFinished && this.raceClock - this.greenClock > 240 && this.endScheduled == null) {
815:       this.endScheduled = this.raceClock;
816:     }
817:     if (this.endScheduled != null && this.raceClock - this.endScheduled > 1.3) {
818:       this.finishRace();
819:     }
820:   }
