822:   finishRace() {
823:     if (this.mode !== "race") return;
824:     this.mode = "result";
825:     this.cameraMode = "chase";
826:     const totalPlayer = this.playerFinished ? this.playerFinishClock - this.greenClock : Infinity;
827:     const totalRival = this.rivalFinished ? this.rivalFinishClock - this.greenClock : Infinity;
828:     const dnf = !this.playerFinished;
829:     const win = !this.foul && !dnf && totalPlayer < totalRival;
830:     const margin = win
831:       ? Math.max(0, (this.rivalFinished ? totalRival : totalPlayer + 1) - totalPlayer)
832:       : this.rivalFinished ? Math.abs(totalPlayer - totalRival) : 0;
833: 
834:     const info = this.rivalInfo;
835:     let prize = 0;
836:     if (!this.foul && !dnf) prize = win ? info.reward : Math.round(info.reward * 0.2);
837:     const prevBest = this.save.bestET;
838:     const record = !this.foul && !dnf && this.playerET != null && (prevBest == null || this.playerET < prevBest);
839: 
840:     if (!this.foul && !dnf) {
841:       this.save.races++;
842:       if (win) {
843:         this.save.wins++;
844:         this.save.careerWins++;
845:       } else {
846:         this.save.losses++;
847:       }
848:       if (this.playerET != null && (this.save.bestET == null || this.playerET < this.save.bestET)) this.save.bestET = this.playerET;
849:       if (this.playerTrap && (this.save.bestTrap == null || this.playerTrap > this.save.bestTrap)) this.save.bestTrap = this.playerTrap;
850:     } else {
851:       this.save.races++;
852:       this.save.losses++;
853:     }
854:     const champion = win && this.save.careerWins === RIVALS.length;
855:     if (champion) prize += 5000;
856:     this.save.money += prize;
857:     persist(this.save);
858: 
859:     const playedChampion = win && this.save.careerWins >= RIVALS.length;
860:     this.ui.showResults({
861:       win,
862:       foul: this.foul,
863:       dnf,
864:       et: this.playerET,
865:       reaction: this.playerReaction,
866:       trap: this.playerTrap,
867:       rivalET: this.rivalET,
868:       rivalName: info.name,
869:       margin,
870:       prize,
871:       record,
872:       kicker: champion ? "CAMPEÃO DA TEMPORADA" : this.foul ? "DESCLASSIFICADO" : "RESULTADO OFICIAL",
873:       sub: champion
874:         ? "Você limpou a fila inteira. O asfalto agora tem dono — e é você."
875:         : playedChampion && win
876:           ? "O rei caiu de novo. A fila vai ficar brava e voltar mais forte."
877:           : this.foul
878:             ? "Você soltou a embreagem antes do verde. O fiscal não perdoou."
879:             : undefined,
880:     });
881:     if (this.foul) this.audio.foul();
882:     else if (win) this.audio.win();
883:     else this.audio.lose();
884:     this.speedlines.style.opacity = "0";
885:     this.ui.showFoul(false);
886:   }
