70: function solveElbow(shoulder, target, l1, l2, pole, out) {
71:   const dx = target.x - shoulder.x, dy = target.y - shoulder.y, dz = target.z - shoulder.z;
72:   let dist = Math.hypot(dx, dy, dz);
73:   dist = Math.min(Math.max(dist, 0.001), l1 + l2 - 0.002);
74:   const ux = dx / dist, uy = dy / dist, uz = dz / dist;
75:   const a = (l1 * l1 - l2 * l2 + dist * dist) / (2 * dist);
76:   const h = Math.sqrt(Math.max(0, l1 * l1 - a * a));
77:   let px = pole.x - ux * (pole.x * ux + pole.y * uy + pole.z * uz);
78:   let py = pole.y - uy * (pole.x * ux + pole.y * uy + pole.z * uz);
79:   let pz = pole.z - uz * (pole.x * ux + pole.y * uy + pole.z * uz);
80:   const pl = Math.hypot(px, py, pz) || 1;
81:   px /= pl; py /= pl; pz /= pl;
82:   out.set(shoulder.x + ux * a + px * h, shoulder.y + uy * a + py * h, shoulder.z + uz * a + pz * h);
83:   return out;
84: }
